-- El logo pasa a guardarse en la base de datos (sobrevive a los despliegues) y
-- los umbrales de tardanza de cocina pasan a ser del negocio
-- AlterTable
ALTER TABLE "Negocio" ADD COLUMN     "logo" BYTEA,
ADD COLUMN     "logoTipo" TEXT,
ADD COLUMN     "umbralMuyTardeMin" INTEGER NOT NULL DEFAULT 25,
ADD COLUMN     "umbralTardaMin" INTEGER NOT NULL DEFAULT 15;


-- El logo de la Cevichería Valentina estaba en backend/public/uploads: se copia
-- a la base y su dirección pasa a ser la del endpoint que lo sirve
UPDATE "Negocio"
SET "logo" = decode('', 'base64'),
    "logoTipo" = 'image/png',
    "logoUrl" = '/api/negocios/' || "codigo" || '/logo?v=1'
WHERE "logoUrl" = '/uploads/negocios/valentina.png';
